def check():
    for name,source in FILES.items():
        if name.endswith(".py"):
            compile(source,name,"exec")
        elif name.endswith(".json"):
            json.loads(source)
    env={}
    exec(FILES["telemetry.py"],env)
    d=env["decode"]({"run_state":5,"battary_life":96,"suction_grade":3,
                     "s_area":46,"s_time":55,"err_state":2105,"water_grade":12})
    assert d["activity"]=="docked" and d["battery_level"]==96
    assert d["fan_speed"]=="Turbo" and d["water_grade"]=="medium"
    assert env["decode"]({"battary_life":999})["battery_level"] is None
    d=env["consumables"]([402,402,402,15])
    assert d["main_brush_left"]==-42 and d["side_brush_remaining_pct"]==0
    assert d["mop_left"]==165
    assert env["consumables"]([])=={}
    assert env["room_command_params"](0,[11,12])==[0,1,2,11,12]
    for rooms in ([],[0],[1,1],["11"]):
        try: env["room_command_params"](0,rooms)
        except ValueError: pass
        else: raise AssertionError("Invalid room selection accepted")
    print("Syntax, manifests and decoder self-tests: PASS")

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument("--apply",action="store_true")
    parser.add_argument("--config",default="/config")
    args=parser.parse_args()
    check()
    root=Path(args.config)
    parent=root/"custom_components"
    dest=parent/"xiaomi_viomi"
    if not args.apply:
        print("Dry run:",dest,len(FILES),"files")
        return
    if not root.is_dir() or dest.is_symlink() or parent.is_symlink():
        raise SystemExit("Unsafe or missing configuration path")
    parent.mkdir(exist_ok=True)
    backup=root/("viomi-backup-"+str(time.time_ns()))
    with tempfile.TemporaryDirectory(prefix=".viomi-stage-",dir=parent) as tmp:
        staged=Path(tmp)/"xiaomi_viomi"
        staged.mkdir()
        for name,source in FILES.items():
            p=staged/name
            p.parent.mkdir(parents=True,exist_ok=True)
            p.write_text(source,encoding="utf-8")
        if dest.exists():
            shutil.move(str(dest),str(backup))
        try:
            os.replace(staged,dest)
        except BaseException:
            if backup.exists():
                shutil.move(str(backup),str(dest))
            raise
    print("Installed:",dest)
    if backup.exists():
        print("Rollback directory:",backup)
    print("Existing HA entries and credentials unchanged. Run ha core restart.")

if __name__=="__main__":
    main()
